"""持久任务恢复、租户生命周期、文件路径、指标与本地性能抽样。"""
from http_client import Client
import unittest,urllib.request,urllib.error,json,uuid,time,subprocess,pathlib,os,statistics,zipfile,io
BASE='http://localhost:8081'
TAG='OPS'+uuid.uuid4().hex[:8]
def sql(query):
 r=subprocess.run(['docker','compose','exec','-T','db','psql','-U','mdm','-d','mdm_test','-At','-v','ON_ERROR_STOP=1','-c',query],capture_output=True,text=True,check=True);return r.stdout.strip()
def upload(c,path,fields,name,content):
 boundary=uuid.uuid4().hex;parts=[]
 for k,v in fields.items():parts.append(f'--{boundary}\r\nContent-Disposition: form-data; name="{k}"\r\n\r\n{v}\r\n'.encode())
 parts.append(f'--{boundary}\r\nContent-Disposition: form-data; name="file"; filename="{name}"\r\nContent-Type: application/octet-stream\r\n\r\n'.encode()+content+b'\r\n');parts.append(f'--{boundary}--\r\n'.encode())
 req=urllib.request.Request(BASE+'/api/v1'+path,data=b''.join(parts),headers={'X-Tenant-Code':c.tenant,'Idempotency-Key':uuid.uuid4().hex,'Content-Type':'multipart/form-data; boundary='+boundary},method='POST')
 return json.load(c.opener.open(req))
def restart():
 pid=int(pathlib.Path('.runtime/test-backend.pid').read_text());os.kill(pid,15)
 for _ in range(100):
  try:urllib.request.urlopen(BASE+'/actuator/health',timeout=.2);time.sleep(.05)
  except Exception:break
 jars=sorted(pathlib.Path('.runtime').glob('test-app-*.jar'),key=lambda p:p.stat().st_mtime);env=dict(os.environ);env.update(PORT='8081',DATABASE_URL='jdbc:postgresql://localhost:5432/mdm_test',RETRY_DELAYS='1,1,1,1',WORKER_DELAY='100',JAVA_HOME='/workspace/.tools/jdk-21.0.6+7')
 with open('.runtime/test-backend.log','ab') as f:p=subprocess.Popen([env['JAVA_HOME']+'/bin/java','-jar',str(jars[-1].resolve())],stdout=f,stderr=f,env=env,start_new_session=True)
 pathlib.Path('.runtime/test-backend.pid').write_text(str(p.pid))
 for _ in range(100):
  try:urllib.request.urlopen(BASE+'/actuator/health',timeout=.5);return
  except Exception:time.sleep(.1)
 raise AssertionError('测试实例未恢复')
class Operations(unittest.TestCase):
 @classmethod
 def setUpClass(cls):
  cls.e=Client('editor','TENANT-B',BASE);cls.r=Client('reviewer','TENANT-B',BASE);cls.a=Client('admin','TENANT-B',BASE);cls.s=cls.e.call('/categories/GLASS_CLOTH/schema');cls.evidence=[]
 def job(self,n=1):
  csv='materialName,model,width,basisWeight,manufacturer\n'+''.join(f'{TAG}{i},{TAG}{uuid.uuid4().hex[:8]},1270,210,SUP-001\n' for i in range(n))
  f=upload(self.e,'/import-files',{'categoryCode':'GLASS_CLOTH'},TAG+'.csv',csv.encode())
  mapping={k:('materialName' if k=='materialName' else {'target':'attributes.'+k,'unit':{'width':'mm','basisWeight':'g/m2'}.get(k,'')}) for k in ['materialName','model','width','basisWeight','manufacturer']}
  return self.e.call('/import-jobs','POST',{'fileId':f['fileId'],'categoryCode':'GLASS_CLOTH','schemaVersionId':self.s['id'],'sheet':'CSV','mapping':mapping},expected=202)
 def wait(self,j,status):
  for _ in range(500):
   x=self.e.call('/import-jobs/'+j['id'])
   if x['status']==status:return x
   time.sleep(.03)
  self.fail(str(x))
 def test_01_precheckPauseRestartResume(self):
  j=self.job(200);before=sql('select count(*) from material; select count(*) from outbox_event; select count(*) from number_sequence;')
  j=self.e.call('/import-jobs/'+j['id']+'/validate','POST',{},j['rowVersion']);j=self.wait(j,'READY');self.assertEqual(before,sql('select count(*) from material; select count(*) from outbox_event; select count(*) from number_sequence;'))
  j=self.e.call('/import-jobs/'+j['id']+'/commit','POST',{'onlyPassed':True},j['rowVersion'])
  # Pause through the API while the durable worker is running.
  for _ in range(100):
   j=self.e.call('/import-jobs/'+j['id'])
   if any(r['state']=='SUCCEEDED' for r in j['rows']):break
   time.sleep(.01)
  j=self.e.call('/import-jobs/'+j['id']+'/pause','POST',{'reason':'重启恢复验收'},j['rowVersion']);saved={r['rowNo']:r['materialId'] for r in j['rows'] if r['state']=='SUCCEEDED'};self.assertGreater(len(saved),0)
  t=self.a.call('/platform/tenants');t=next(t for t in t if t['code']=='TENANT-B');t=self.a.call('/platform/tenants/'+t['id']+'/suspend','POST',{'reason':'暂停恢复验收'},t['rowVersion']);self.e.call('/materials','POST',{},expected=409);restart();self.__class__.e=Client('editor','TENANT-B',BASE);self.__class__.r=Client('reviewer','TENANT-B',BASE);self.__class__.a=Client('admin','TENANT-B',BASE)
  self.assertEqual('PAUSED',self.e.call('/import-jobs/'+j['id'])['status']);self.a.call('/platform/tenants/'+t['id']+'/resume','POST',{'reason':'恢复验收'},t['rowVersion']);j=self.e.call('/import-jobs/'+j['id']);self.e.call('/import-jobs/'+j['id']+'/resume','POST',{},j['rowVersion']);j=self.wait(j,'COMPLETED');self.assertEqual(200,sum(r['state']=='SUCCEEDED' for r in j['rows']));self.assertEqual(200,len(set(r['materialId'] for r in j['rows'])));self.assertTrue(all(saved[r['rowNo']]==r['materialId'] for r in j['rows'] if r['rowNo'] in saved));self.evidence.append({'importRestartRows':200,'successfulRowsBeforeRestart':len(saved),'replayed':0})
