 def test_08_postgresSkipLockedAndTenantForeignKeys(self):
  one=self.job(1);two=self.job(1);ids=[one['id'],two['id']];query="begin;select id from import_job where id in ('"+ids[0]+"','"+ids[1]+"') order by id for update skip locked limit 1;select pg_sleep(1);commit;"
  cmd=['docker','compose','exec','-T','db','psql','-U','mdm','-d','mdm_test','-At','-v','ON_ERROR_STOP=1','-c',query]
  first=subprocess.Popen(cmd,stdout=subprocess.PIPE,stderr=subprocess.PIPE,text=True);time.sleep(.1);second=subprocess.Popen(cmd,stdout=subprocess.PIPE,stderr=subprocess.PIPE,text=True);a=first.communicate(timeout=5)[0];b=second.communicate(timeout=5)[0];self.assertEqual(0,first.returncode);self.assertEqual(0,second.returncode);claimed=[next(x for x in out.splitlines() if x in ids) for out in [a,b]];self.assertEqual(2,len(set(claimed)))
  other=Client('editor','TENANT-A',BASE);f=upload(other,'/import-files',{'categoryCode':'GLASS_CLOTH'},'隔离.csv',b'materialName,model\nA,A\n');query="begin;update import_job set file_id='"+f['fileId']+"' where id='"+one['id']+"';rollback;";r=subprocess.run(['docker','compose','exec','-T','db','psql','-U','mdm','-d','mdm_test','-v','ON_ERROR_STOP=1','-c',query],capture_output=True,text=True);self.assertNotEqual(0,r.returncode);self.assertIn('foreign key',r.stderr.lower())
  for j in [one,two]:self.e.call('/import-jobs/'+j['id']+'/cancel','POST',{},j['rowVersion'])
  self.evidence.append({'postgresSkipLockedTwoConnections':'distinct claims','crossTenantTaskForeignKey':'rejected'})
